create or replace function public.append_audit_event_chained(
  p_id uuid,
  p_organization_id uuid,
  p_actor_user_id uuid,
  p_action text,
  p_entity_type text,
  p_entity_id text,
  p_metadata jsonb,
  p_created_at timestamptz,
  p_previous_hash text,
  p_event_hash text,
  p_hash_signature text default null,
  p_hash_algorithm text default 'sha256'
)
returns public.audit_events
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_previous_hash text;
  v_inserted public.audit_events;
begin
  if p_id is null then
    raise exception 'id is required' using errcode = '23502';
  end if;
  if p_organization_id is null then
    raise exception 'organization_id is required' using errcode = '23502';
  end if;
  if p_action is null or length(trim(p_action)) = 0 then
    raise exception 'action is required' using errcode = '23502';
  end if;
  if p_entity_type is null or length(trim(p_entity_type)) = 0 then
    raise exception 'entity_type is required' using errcode = '23502';
  end if;
  if p_created_at is null then
    raise exception 'created_at is required' using errcode = '23502';
  end if;
  if p_event_hash is null or length(trim(p_event_hash)) = 0 then
    raise exception 'event_hash is required' using errcode = '23502';
  end if;
  if p_hash_algorithm is null or p_hash_algorithm <> 'sha256' then
    raise exception 'hash_algorithm must be sha256' using errcode = '22023';
  end if;

  -- Fail fast on same-organization contention so PostgREST workers are not
  -- consumed waiting on an advisory lock. The application already retries
  -- SQLSTATE 40001 with bounded exponential backoff and jitter.
  if not pg_try_advisory_xact_lock(hashtext(p_organization_id::text)) then
    raise exception 'audit chain append contention' using errcode = '40001';
  end if;

  select ae.event_hash
    into v_previous_hash
  from public.audit_events ae
  where ae.organization_id = p_organization_id
    and ae.event_hash is not null
  order by ae.created_at desc, ae.id desc
  limit 1;

  if coalesce(v_previous_hash, '') <> coalesce(p_previous_hash, '') then
    raise exception 'audit chain previous hash mismatch' using errcode = '40001';
  end if;

  insert into public.audit_events (
    id, organization_id, actor_user_id, action, entity_type, entity_id,
    metadata, created_at, previous_hash, event_hash, hash_algorithm, hash_signature
  ) values (
    p_id, p_organization_id, p_actor_user_id, p_action, p_entity_type, p_entity_id,
    coalesce(p_metadata, '{}'::jsonb), p_created_at, v_previous_hash, p_event_hash,
    p_hash_algorithm, p_hash_signature
  )
  returning * into v_inserted;

  return v_inserted;
end;
$$;

revoke all on function public.append_audit_event_chained(uuid,uuid,uuid,text,text,text,jsonb,timestamptz,text,text,text,text) from public, anon, authenticated;
grant execute on function public.append_audit_event_chained(uuid,uuid,uuid,text,text,text,jsonb,timestamptz,text,text,text,text) to service_role;
notify pgrst, 'reload schema';

create or replace function public.append_audit_event_chained(
  p_id uuid,
  p_organization_id uuid,
  p_actor_user_id uuid,
  p_action text,
  p_entity_type text,
  p_entity_id text,
  p_metadata jsonb,
  p_created_at timestamptz,
  p_previous_hash text,
  p_event_hash text,
  p_hash_signature text default null,
  p_hash_algorithm text default 'sha256'
) returns public.audit_events
language plpgsql
security definer
set search_path = pg_catalog
as $$
declare
  v_previous_hash text;
  v_inserted public.audit_events;
begin
  if p_id is null then
    raise exception 'id is required' using errcode = '23502';
  end if;
  if p_organization_id is null then
    raise exception 'organization_id is required' using errcode = '23502';
  end if;
  if p_action is null or length(trim(p_action)) = 0 then
    raise exception 'action is required' using errcode = '23502';
  end if;
  if p_entity_type is null or length(trim(p_entity_type)) = 0 then
    raise exception 'entity_type is required' using errcode = '23502';
  end if;
  if p_created_at is null then
    raise exception 'created_at is required' using errcode = '23502';
  end if;
  if p_event_hash is null or length(trim(p_event_hash)) = 0 then
    raise exception 'event_hash is required' using errcode = '23502';
  end if;
  if p_hash_algorithm is null or p_hash_algorithm <> 'sha256' then
    raise exception 'hash_algorithm must be sha256' using errcode = '22023';
  end if;

  if not pg_try_advisory_xact_lock(hashtext(p_organization_id::text)) then
    raise exception 'audit chain write conflict: lock unavailable' using errcode = '55P03';
  end if;

  select ae.event_hash
    into v_previous_hash
  from public.audit_events ae
  where ae.organization_id = p_organization_id
    and ae.event_hash is not null
  order by ae.created_at desc, ae.id desc
  limit 1;

  if coalesce(v_previous_hash, '') <> coalesce(p_previous_hash, '') then
    raise exception 'audit chain write conflict: stale head' using errcode = 'P0001';
  end if;

  insert into public.audit_events (
    id, organization_id, actor_user_id, action, entity_type, entity_id,
    metadata, created_at, previous_hash, event_hash, hash_algorithm, hash_signature
  ) values (
    p_id, p_organization_id, p_actor_user_id, p_action, p_entity_type, p_entity_id,
    coalesce(p_metadata, '{}'::jsonb), p_created_at, v_previous_hash, p_event_hash,
    p_hash_algorithm, p_hash_signature
  )
  returning * into v_inserted;

  return v_inserted;
end;
$$;

revoke all on function public.append_audit_event_chained(uuid,uuid,uuid,text,text,text,jsonb,timestamptz,text,text,text,text) from public, anon, authenticated;
grant execute on function public.append_audit_event_chained(uuid,uuid,uuid,text,text,text,jsonb,timestamptz,text,text,text,text) to service_role;
comment on function public.append_audit_event_chained(uuid,uuid,uuid,text,text,text,jsonb,timestamptz,text,text,text,text) is 'Enterprise append-only audit-chain writer. P0 emergency fail-closed conflict signaling uses non-retryable codes/messages to contain stale generic-retry clients; normal successful append semantics are unchanged.';

create schema if not exists app_private;

do $$
begin
  if to_regprocedure('public.enterprise_member_can_read(uuid)') is not null then
    if to_regprocedure('app_private.enterprise_member_can_read(uuid)') is not null then
      raise exception 'duplicate enterprise_member_can_read helper exists in app_private';
    end if;
    execute 'alter function public.enterprise_member_can_read(uuid) set schema app_private';
  end if;

  if to_regprocedure('public.enterprise_member_can_manage(uuid)') is not null then
    if to_regprocedure('app_private.enterprise_member_can_manage(uuid)') is not null then
      raise exception 'duplicate enterprise_member_can_manage helper exists in app_private';
    end if;
    execute 'alter function public.enterprise_member_can_manage(uuid) set schema app_private';
  end if;
end
$$;

revoke all on function app_private.enterprise_member_can_read(uuid) from public, anon;
revoke all on function app_private.enterprise_member_can_manage(uuid) from public, anon;
grant execute on function app_private.enterprise_member_can_read(uuid) to authenticated, service_role;
grant execute on function app_private.enterprise_member_can_manage(uuid) to authenticated, service_role;

create or replace function public.is_organization_member(p_organization_id uuid)
returns boolean
language sql
stable
security invoker
set search_path = ''
as $$
  select app_private.enterprise_member_can_read(p_organization_id);
$$;

revoke all on function public.is_organization_member(uuid) from public, anon;
grant execute on function public.is_organization_member(uuid) to authenticated, service_role;

alter function public.prevent_ai_qms_decision_mutation()
  set search_path = pg_catalog;

do $$
declare
  decision_search_path text[];
  compatibility_definition text;
  compatibility_security_definer boolean;
begin
  if to_regprocedure('public.enterprise_member_can_read(uuid)') is not null
     or to_regprocedure('public.enterprise_member_can_manage(uuid)') is not null then
    raise exception 'Enterprise membership SECURITY DEFINER helpers remain exposed in public schema';
  end if;

  if to_regprocedure('app_private.enterprise_member_can_read(uuid)') is null
     or to_regprocedure('app_private.enterprise_member_can_manage(uuid)') is null then
    raise exception 'Enterprise membership helpers are missing from app_private';
  end if;

  if not has_function_privilege('authenticated', 'app_private.enterprise_member_can_read(uuid)', 'EXECUTE')
     or not has_function_privilege('authenticated', 'app_private.enterprise_member_can_manage(uuid)', 'EXECUTE') then
    raise exception 'Authenticated RLS helper execution grant is missing';
  end if;

  if has_function_privilege('anon', 'app_private.enterprise_member_can_read(uuid)', 'EXECUTE')
     or has_function_privilege('anon', 'app_private.enterprise_member_can_manage(uuid)', 'EXECUTE') then
    raise exception 'Anonymous role can execute private Enterprise membership helpers';
  end if;

  if to_regprocedure('public.is_organization_member(uuid)') is null then
    raise exception 'Membership compatibility wrapper is missing';
  end if;

  select pg_get_functiondef(p.oid), p.prosecdef
    into compatibility_definition, compatibility_security_definer
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.proname = 'is_organization_member'
    and pg_get_function_identity_arguments(p.oid) = 'p_organization_id uuid';

  if compatibility_definition is null
     or position('app_private.enterprise_member_can_read' in compatibility_definition) = 0 then
    raise exception 'Membership compatibility wrapper does not target app_private.enterprise_member_can_read';
  end if;

  if compatibility_security_definer is distinct from false then
    raise exception 'Membership compatibility wrapper must remain SECURITY INVOKER';
  end if;

  if not has_function_privilege('authenticated', 'public.is_organization_member(uuid)', 'EXECUTE')
     or has_function_privilege('anon', 'public.is_organization_member(uuid)', 'EXECUTE') then
    raise exception 'Membership compatibility wrapper grants are not fail-closed';
  end if;

  if exists (
    select 1
    from pg_policies
    where (coalesce(qual, '') ilike '%enterprise_member_can_read%'
           or coalesce(with_check, '') ilike '%enterprise_member_can_read%')
      and coalesce(qual, '') not ilike '%app_private.enterprise_member_can_read%'
      and coalesce(with_check, '') not ilike '%app_private.enterprise_member_can_read%'
  ) then
    raise exception 'An RLS policy still resolves enterprise_member_can_read outside app_private';
  end if;

  select p.proconfig
    into decision_search_path
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.proname = 'prevent_ai_qms_decision_mutation'
    and pg_get_function_identity_arguments(p.oid) = '';

  if decision_search_path is null
     or not ('search_path=pg_catalog' = any(decision_search_path)) then
    raise exception 'prevent_ai_qms_decision_mutation search_path is not fixed to pg_catalog';
  end if;
end
$$;

begin;

do $prerequisites$
begin
  if to_regclass('public.organizations') is null then
    raise exception 'public.organizations is required';
  end if;
  if to_regclass('public.organization_members') is null then
    raise exception 'public.organization_members is required';
  end if;
  if to_regclass('auth.users') is null then
    raise exception 'auth.users is required';
  end if;
end
$prerequisites$;

create table if not exists public.data_retention_policies (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  data_category text not null check (char_length(data_category) between 2 and 80),
  retention_days integer not null check (retention_days between 1 and 3650),
  legal_basis text not null check (char_length(legal_basis) between 2 and 120),
  deletion_mode text not null default 'hard_delete' check (deletion_mode in ('hard_delete','anonymize','archive')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, data_category)
);

create table if not exists public.data_subject_requests (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  requester_user_id uuid not null references auth.users(id) on delete cascade,
  request_type text not null check (request_type in ('access','export','rectification','restriction','deletion','objection')),
  status text not null default 'received' check (status in ('received','verified','in_progress','completed','rejected','cancelled')),
  due_at timestamptz not null default (now() + interval '30 days'),
  completed_at timestamptz,
  resolution_summary text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((status = 'completed' and completed_at is not null) or status <> 'completed')
);

create table if not exists public.audit_integrity_checkpoints (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  source_table text not null,
  range_started_at timestamptz not null,
  range_ended_at timestamptz not null,
  event_count bigint not null check (event_count >= 0),
  digest_sha256 text not null check (digest_sha256 ~ '^[a-f0-9]{64}$'),
  previous_digest_sha256 text check (previous_digest_sha256 is null or previous_digest_sha256 ~ '^[a-f0-9]{64}$'),
  generated_at timestamptz not null default now(),
  generated_by uuid references auth.users(id),
  check (range_ended_at >= range_started_at)
);

alter table public.data_retention_policies enable row level security;
alter table public.data_retention_policies force row level security;
alter table public.data_subject_requests enable row level security;
alter table public.data_subject_requests force row level security;
alter table public.audit_integrity_checkpoints enable row level security;
alter table public.audit_integrity_checkpoints force row level security;

revoke all privileges on table public.data_retention_policies from anon, authenticated;
revoke all privileges on table public.data_subject_requests from anon, authenticated;
revoke all privileges on table public.audit_integrity_checkpoints from anon, authenticated;
grant select on table public.data_retention_policies to authenticated;
grant select on table public.data_subject_requests to authenticated;
grant select on table public.audit_integrity_checkpoints to authenticated;
grant all privileges on table public.data_retention_policies to service_role;
grant all privileges on table public.data_subject_requests to service_role;
grant all privileges on table public.audit_integrity_checkpoints to service_role;

drop policy if exists "retention policies organization members read" on public.data_retention_policies;
create policy "retention policies organization members read"
  on public.data_retention_policies
  for select
  to authenticated
  using (
    exists (
      select 1
      from public.organization_members m
      where m.organization_id = data_retention_policies.organization_id
        and m.user_id = auth.uid()
        and coalesce(m.status, 'active') = 'active'
    )
  );

drop policy if exists "data subjects read own requests" on public.data_subject_requests;
create policy "data subjects read own requests"
  on public.data_subject_requests
  for select
  to authenticated
  using (
    requester_user_id = auth.uid()
    or exists (
      select 1
      from public.organization_members m
      where m.organization_id = data_subject_requests.organization_id
        and m.user_id = auth.uid()
        and coalesce(m.status, 'active') = 'active'
        and m.role in ('owner','admin')
    )
  );

drop policy if exists "audit checkpoints organization members read" on public.audit_integrity_checkpoints;
create policy "audit checkpoints organization members read"
  on public.audit_integrity_checkpoints
  for select
  to authenticated
  using (
    exists (
      select 1
      from public.organization_members m
      where m.organization_id = audit_integrity_checkpoints.organization_id
        and m.user_id = auth.uid()
        and coalesce(m.status, 'active') = 'active'
    )
  );

create index if not exists data_subject_requests_org_status_due_idx
  on public.data_subject_requests (organization_id, status, due_at);
create index if not exists audit_integrity_checkpoints_org_generated_idx
  on public.audit_integrity_checkpoints (organization_id, generated_at desc);

do $verify$
declare
  target_table text;
begin
  foreach target_table in array array[
    'data_retention_policies',
    'data_subject_requests',
    'audit_integrity_checkpoints'
  ]
  loop
    if to_regclass(format('public.%I', target_table)) is null then
      raise exception 'data-governance reconciliation failed: public.% missing', target_table;
    end if;

    if not exists (
      select 1
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public'
        and c.relname = target_table
        and c.relrowsecurity
        and c.relforcerowsecurity
    ) then
      raise exception 'data-governance reconciliation failed: RLS/FORCE RLS missing on public.%', target_table;
    end if;

    if has_table_privilege('anon', format('public.%I', target_table), 'SELECT')
       or has_table_privilege('anon', format('public.%I', target_table), 'INSERT')
       or has_table_privilege('anon', format('public.%I', target_table), 'UPDATE')
       or has_table_privilege('anon', format('public.%I', target_table), 'DELETE')
       or has_table_privilege('authenticated', format('public.%I', target_table), 'INSERT')
       or has_table_privilege('authenticated', format('public.%I', target_table), 'UPDATE')
       or has_table_privilege('authenticated', format('public.%I', target_table), 'DELETE')
       or not has_table_privilege('authenticated', format('public.%I', target_table), 'SELECT') then
      raise exception 'data-governance reconciliation failed: browser ACL boundary malformed on public.%', target_table;
    end if;
  end loop;
end
$verify$;

commit;

begin;

do $prerequisite$
begin
  if to_regclass('public.data_subject_requests') is null then
    raise exception 'Canonical public.data_subject_requests table is required';
  end if;
end
$prerequisite$;

alter table public.data_subject_requests
  add column if not exists received_at timestamptz,
  add column if not exists initial_due_at timestamptz,
  add column if not exists identity_verification_state text not null default 'pending',
  add column if not exists identity_verification_requested_at timestamptz,
  add column if not exists identity_verified_at timestamptz,
  add column if not exists role_route text not null default 'under_review',
  add column if not exists customer_controller_reference text,
  add column if not exists extension_reason text,
  add column if not exists extension_notified_at timestamptz,
  add column if not exists extended_due_at timestamptz,
  add column if not exists decision text,
  add column if not exists decision_reason text,
  add column if not exists evidence_refs jsonb not null default '[]'::jsonb;

update public.data_subject_requests
set received_at = coalesce(received_at, created_at, now())
where received_at is null;

update public.data_subject_requests
set initial_due_at = coalesce(initial_due_at, due_at, received_at + interval '1 month')
where initial_due_at is null;

alter table public.data_subject_requests
  alter column received_at set default now(),
  alter column received_at set not null,
  alter column initial_due_at set not null,
  alter column due_at drop default;

alter table public.data_subject_requests
  drop constraint if exists data_subject_requests_request_type_check,
  drop constraint if exists data_subject_requests_status_check,
  drop constraint if exists data_subject_requests_identity_verification_state_check,
  drop constraint if exists data_subject_requests_role_route_check,
  drop constraint if exists data_subject_requests_decision_check,
  drop constraint if exists data_subject_requests_deadline_order_check,
  drop constraint if exists data_subject_requests_extension_integrity_check,
  drop constraint if exists data_subject_requests_evidence_refs_array_check;

alter table public.data_subject_requests
  add constraint data_subject_requests_request_type_check
    check (request_type in ('access','export','rectification','restriction','deletion','objection','portability','consent_withdrawal')),
  add constraint data_subject_requests_status_check
    check (status in ('received','awaiting_identity','verified','in_progress','routed_to_controller','completed','rejected','cancelled')),
  add constraint data_subject_requests_identity_verification_state_check
    check (identity_verification_state in ('pending','not_required','verified','failed')),
  add constraint data_subject_requests_role_route_check
    check (role_route in ('controller','processor','mixed','under_review')),
  add constraint data_subject_requests_decision_check
    check (decision is null or decision in ('fulfilled','partially_fulfilled','refused','withdrawn','routed_to_controller')),
  add constraint data_subject_requests_deadline_order_check
    check (initial_due_at >= received_at and due_at >= initial_due_at),
  add constraint data_subject_requests_extension_integrity_check
    check ((extended_due_at is null and extension_reason is null and extension_notified_at is null) or (extended_due_at is not null and extension_reason is not null and char_length(trim(extension_reason)) between 2 and 1000 and extension_notified_at is not null and extended_due_at = due_at and extended_due_at <= initial_due_at + interval '2 months')),
  add constraint data_subject_requests_evidence_refs_array_check
    check (jsonb_typeof(evidence_refs) = 'array');

alter table public.data_subject_requests
  drop constraint if exists data_subject_requests_check,
  drop constraint if exists data_subject_requests_completion_check;

alter table public.data_subject_requests
  add constraint data_subject_requests_completion_check
    check ((status = 'completed' and completed_at is not null) or status <> 'completed');

alter table public.data_subject_requests enable row level security;
alter table public.data_subject_requests force row level security;

drop policy if exists "data subjects create own requests" on public.data_subject_requests;
drop policy if exists "data subject admins process requests" on public.data_subject_requests;
drop policy if exists "data subject requesters cancel own pending requests" on public.data_subject_requests;

revoke insert, update, delete on table public.data_subject_requests from anon, authenticated;
grant select on table public.data_subject_requests to authenticated;

drop policy if exists "restrict_data_subject_requests_insert_server_only" on public.data_subject_requests;
create policy "restrict_data_subject_requests_insert_server_only"
  on public.data_subject_requests as restrictive for insert to authenticated with check (false);

drop policy if exists "restrict_data_subject_requests_update_server_only" on public.data_subject_requests;
create policy "restrict_data_subject_requests_update_server_only"
  on public.data_subject_requests as restrictive for update to authenticated using (false) with check (false);

drop policy if exists "restrict_data_subject_requests_delete_server_only" on public.data_subject_requests;
create policy "restrict_data_subject_requests_delete_server_only"
  on public.data_subject_requests as restrictive for delete to authenticated using (false);

create index if not exists data_subject_requests_org_received_idx
  on public.data_subject_requests (organization_id, received_at desc);
create index if not exists data_subject_requests_org_due_open_idx
  on public.data_subject_requests (organization_id, due_at)
  where status not in ('completed','rejected','cancelled');

do $verify$
begin
  if not exists (
    select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relname = 'data_subject_requests' and c.relrowsecurity and c.relforcerowsecurity
  ) then
    raise exception 'data_subject_requests RLS/FORCE RLS postcondition failed';
  end if;

  if has_table_privilege('anon', 'public.data_subject_requests', 'INSERT')
     or has_table_privilege('anon', 'public.data_subject_requests', 'UPDATE')
     or has_table_privilege('anon', 'public.data_subject_requests', 'DELETE')
     or has_table_privilege('authenticated', 'public.data_subject_requests', 'INSERT')
     or has_table_privilege('authenticated', 'public.data_subject_requests', 'UPDATE')
     or has_table_privilege('authenticated', 'public.data_subject_requests', 'DELETE')
     or not has_table_privilege('authenticated', 'public.data_subject_requests', 'SELECT') then
    raise exception 'data_subject_requests browser privilege boundary is not least privilege';
  end if;

  if not exists (select 1 from information_schema.columns where table_schema='public' and table_name='data_subject_requests' and column_name='received_at')
     or not exists (select 1 from information_schema.columns where table_schema='public' and table_name='data_subject_requests' and column_name='role_route')
     or not exists (select 1 from information_schema.columns where table_schema='public' and table_name='data_subject_requests' and column_name='extended_due_at') then
    raise exception 'data_subject_requests lifecycle columns missing';
  end if;
end
$verify$;

commit;

begin;

do $tables$
begin
  if to_regclass('public.linkedin_marketing_posts') is not null then
